public class AliasStore {
 private Map<String,List<Integer>> groups=new Map<String,List<Integer>>{'items'=>new List<Integer>{1,2}};
 public List<Integer> read(){return groups.get('items');}
 public void drop(Integer index){groups.get('items').remove(index);}
 public static Map<String,Object> observe(String mode){
  Map<String,Object> p=new Map<String,Object>{'mode'=>mode};
  List<Integer> visited=new List<Integer>();p.put('visited',visited);
  if(mode=='snapshot'){
   Map<String,Integer> source=new Map<String,Integer>{'a'=>1,'b'=>2};
   List<Integer> snapshot=source.values();
   for(Integer item:snapshot){source.remove('a');visited.add(item);}
   p.put('final',snapshot);p.put('mapSize',source.size());p.put('complete',true);return p;
  }
  AliasStore store=new AliasStore();List<Integer> cached=store.read();
  p.put('final',cached);
  try{
   if(mode=='nested'){
    List<Integer> targets=new List<Integer>{1,2};
    for(Integer item:cached){visited.add(item);for(Integer target:targets){if(item==target)store.drop(cached.indexOf(item));}}
   }else{
    for(Integer item:cached){visited.add(item);if(item==1){store.drop(0);if(mode=='break')break;}}
   }
   p.put('complete',true);
  }catch(Exception e){p.put('type',e.getTypeName());p.put('message',e.getMessage());p.put('caught',true);}
  p.put('stored',store.read());return p;
 }
}

